_DSTORY = 'בחנות ״עדשה״ היו בתחילת השנה 100 משקפי שמש בעלות 10 ש״ח ליחידה. במהלך השנה נקנו 100 יחידות ב-12 ש״ח, ואחר כך 200 יחידות ב-15 ש״ח. נמכרו 250 יחידות ב-20 ש״ח ליחידה.'


def COGS(open_, buy, close, rev, notes=None, close_lab='בניכוי מלאי סגירה (ערך חשבונאי)', hl=None):
    """Stages 5 and 6 as two cards: the fixed cost of sales table, then sales less cost of sales."""
    n = notes or {}
    hl = hl or {}
    cg = open_ + buy - close
    s5 = STG(5, 'עלות המכר: הטבלה הקבועה', ['', 'ש״ח'], [
        RW('op', ['מלאי פתיחה', C(open_, '', n.get('op', 'מה שהיה במחסן בתחילת השנה.'), hl=hl.get('op', ()))]),
        RW('by', ['קניות', C(buy, '', n.get('by', 'כל מה שנקנה השנה.'), hl=hl.get('by', ()))]),
        RW('cl', [close_lab, C(-close, '', n.get('cl', 'מה שנשאר, בסכום שבו הוא מוצג במאזן.'))]),
        RW('cg', ['עלות המכר', C(cg, '=B#op#:B#cl#', n.get('cg', f'מה שהיה, ועוד מה שנקנה, פחות מה שנשאר: ${f2(open_)} + {f2(buy)} - {f2(close)} = {f2(cg)}$. זה מה שנמכר.'))], 'bal')], widths=[64, 36])
    s6 = STG(6, 'רווח גולמי', ['', 'ש״ח'], [
        RW('sl', ['מכירות', C(rev, '', n.get('sl', 'יחידות שנמכרו כפול מחיר המכירה.'), hl=hl.get('sl', ()))]),
        RW('cg', ['בניכוי עלות המכר', C(-cg, '', 'משלב 5.')], 'prev'),
        RW('gp', ['רווח גולמי', C(rev - cg, '=B#sl#:B#cg#', f'מכירות פחות עלות המכר: ${f2(rev)} - {f2(cg)} = {f2(rev - cg)}$.')], 'net')], widths=[64, 36])
    return [s5, s6]


def COGS2(r, use_bv=False, notes=('', '')):
    """Stages 5 and 6 for FIFO beside average, one column per method."""
    cl = [r['fifo_bv'], r['avg_bv']] if use_bv else [r['fifo'], r['avg']]
    cg = [r['tc'] - c for c in cl]
    s5 = STG(5, 'עלות המכר', ['', 'FIFO', 'ממוצע'], [
        RW('op', ['מלאי פתיחה', r['open'], r['open']]),
        RW('by', ['קניות', r['buy'], r['buy']]),
        RW('cl', ['בניכוי מלאי סגירה' + (' (ערך חשבונאי)' if use_bv else ''), C(-cl[0], '', notes[0] or 'ב-FIFO נשארו היחידות היקרות.'), C(-cl[1], '', notes[1] or 'בממוצע כל יחידה באותה עלות.')]),
        RW('cg', ['עלות המכר', C(cg[0], '=B#op#:B#cl#', f'${r["open"]:,} + {r["buy"]:,} - {cl[0]:,} = {cg[0]:,}$.'), C(cg[1], '=C#op#:C#cl#', f'${r["open"]:,} + {r["buy"]:,} - {cl[1]:,} = {cg[1]:,}$.')], 'bal')], widths=[46, 27, 27], center=True)
    s6 = STG(6, 'רווח גולמי', ['', 'FIFO', 'ממוצע'], [
        RW('sl', ['מכירות', r['rev'], r['rev']]),
        RW('cg', ['בניכוי עלות המכר', -cg[0], -cg[1]], 'prev'),
        RW('gp', ['רווח גולמי', C(r['rev'] - cg[0], '=B#sl#:B#cg#', f'${r["rev"]:,} - {cg[0]:,} = {r["rev"] - cg[0]:,}$.'), C(r['rev'] - cg[1], '=C#sl#:C#cg#', f'${r["rev"]:,} - {cg[1]:,} = {r["rev"] - cg[1]:,}$.')], 'net')], widths=[46, 27, 27], center=True)
    return [s5, s6]


def ANS(rows):
    """The last card of an inventory exercise: the answer to each requirement."""
    return STG('התשובות', 'מה עונים בכל נדרש', ['', 'ש״ח'], [RW(f'a{i}', [lab, C(v, '', x)], 'net' if i == len(rows) - 1 else '') for i, (lab, v, x) in enumerate(rows)], widths=[66, 34])


