_L = 'BCDEF'


def _dir(v):
    return 'הרווח עולה' if v > 0 else ('הרווח יורד' if v < 0 else 'אין השפעה')


def ERRT(yrs, rows_, errs):
    """The year table of inventory errors: per year the closing correction, the arrow to next year's opening, the opening correction, the corrected profit."""
    pc = ['השפעת תיקון מ״ס (שלב 2)'] + [C(r['pc'], '', ('מ״ס נמדד נכון: אין מה לתקן.' if not r['pc'] else f'מ״ס של {y} הוערך {"ביתר" if r["pc"] < 0 else "בחסר"}: {"מקטינים" if r["pc"] < 0 else "מגדילים"} אותו ב-{abs(r["pc"]):,}, ו{_dir(r["pc"])} ב-{abs(r["pc"]):,}. אותו כיוון כמו התיקון.'), o=10 * i + 1) for i, (y, r) in enumerate(zip(yrs, rows_))]
    po = ['השפעת תיקון מ״פ (שלב 3)'] + [C(r['po'], '', 'השנה הראשונה: מלאי הפתיחה נכון, אין מה לתקן.' if not i else f'מ״פ של {y} הוא המ״ס של {y - 1}, בסימן הפוך: {_dir(r["po"])}' + (f' ב-{abs(r["po"]):,}.' if r['po'] else '.'), o=10 * i + 2) for i, (y, r) in enumerate(zip(yrs, rows_))]
    fx = ['רווח גולמי מתוקן (שלב 4)'] + [C(r['fixed'], f'={_L[i]}#gp#:{_L[i]}#po#', f'${r["gp"]:,} {"+" if r["pc"] >= 0 else "-"} {abs(r["pc"]):,} {"+" if r["po"] >= 0 else "-"} {abs(r["po"]):,} = {r["fixed"]:,}$.', o=10 * i + 3) for i, r in enumerate(rows_)]
    arr = [AR(f'pc:{_L[i - 1]}', f'po:{_L[i]}', 10 * i + 2, f'<b>המעבר מ-{y - 1} ל-{y}:</b> מלאי הסגירה של {y - 1} הוא מלאי הפתיחה של {y}. תיקנו אותו ב-{y - 1} ' + ('כלפי מטה' if rows_[i - 1]['pc'] < 0 else 'כלפי מעלה') + f', ולכן ב-{y} ההשפעה הפוכה: {_dir(rows_[i]["po"])} ב-{abs(rows_[i]["po"]):,}.') for i, y in enumerate(yrs) if i and rows_[i - 1]['pc']]
    return STG(None, 'שנה אחר שנה: מ״ס, החץ אל השנה הבאה, ואז מ״פ', ['', *[str(y) for y in yrs]], [
        RW('gp', ['רווח גולמי לפני תיקון (שלב 1)'] + [r['gp'] for r in rows_], o=0),
        RW('pc', pc), RW('po', po), RW('fx', fx, 'net')], arr, widths=[31] + [69 / len(yrs)] * len(yrs), center=True)


def ERRL(yrs, rows_, errs):
    """The live sheet of an inventory error question."""
    L = _L[:len(yrs)]
    return LIVE(['', *[str(y) for y in yrs]], [
        LR('gp', ['רווח גולמי לפני תיקון'] + [r['gp'] for r in rows_], 'שלב 1: הרווח שדווח, מן השאלה.'),
        LR('er', ['טעות במ״ס: יתר (+), חסר (−)'] + list(errs), 'הטעות בכל שנה: הערכת יתר בפלוס, הערכת חסר במינוס, ונמדד נכון: 0.'),
        LR('pc', ['השפעת תיקון מ״ס'] + [(f'=-{c}#er#', r['pc']) for c, r in zip(L, rows_)], 'שלב 2: מתקנים את המ״ס, והרווח זז הפוך לסימן הטעות. כותבים בשנה הראשונה וגוררים.'),
        LR('po', ['השפעת תיקון מ״פ'] + [0] + [(f'={L[i - 1]}#er#', rows_[i]['po']) for i in range(1, len(yrs))], 'שלב 3: בשנה הראשונה 0. מכאן: הטעות של השנה הקודמת, באותו סימן, כי ההשפעה הפוכה לתיקון של אותה שנה.'),
        LR('fx', ['רווח גולמי מתוקן'] + [(f'=SUM({c}#gp#,{c}#pc#:{c}#po#)', r['fixed']) for c, r in zip(L, rows_)], 'שלב 4: הרווח לפני תיקון, ועוד שתי ההשפעות.', 'net')],
        [190] + [92] * len(yrs), hints=['השפעת תיקון מ״ס: מינוס הטעות של אותה שנה.', 'השפעת תיקון מ״פ: הטעות של השנה הקודמת.'])


