TI = ['תאריך', 'אירוע', 'שווי במאזן (שלב 1)', 'שינוי בשווי (שלב 2)', 'דיבידנד (שלב 3)', 'רווח והפסד (שלב 4)']
TW = [13, 19, 17, 17, 15, 19]


def INVT(rows_):
    """The value table of a trading investment: one row per date. rows_: (key, date, event, value, change, dividend, effect, notes dict)."""
    out = []
    for i, (k, d, ev, v, ch, dv, ef, nt) in enumerate(rows_):
        kind = 'net' if k == 's' else ''
        out.append(RW(k, [d, ev,
                          C(v, '', nt.get('v', '')) if v != '' else '',
                          C(ch, nt.get('fch', ''), nt.get('ch', '')) if ch != '' else '',
                          C(dv, '', nt.get('dv', '')) if dv != '' else '',
                          C(ef, nt.get('fef', ''), nt.get('ef', '')) if ef != '' else ''], kind))
    return STG(None, 'טבלת השווי: שורה לכל תאריך', TI, out, widths=TW, dcol=0, center=True)


def INVL(rows_, sale_price):
    """The live sheet: dates and events are labels; the student types the values and dividends and writes the changes."""
    out = []
    for i, (k, d, ev, v, ch, dv, ef, nt) in enumerate(rows_):
        prev = rows_[i - 1][0] if i else None
        if not i:
            out.append(LR(k, [d, ev, v], 'שלב 1: העלות. ממנה נמדד השינוי של השנה הראשונה.'))
        elif k == 's':
            out.append(LR(k, [d, ev, sale_price, (f'=C#{k}#-C#{prev}#', ch), '', (f'=D#{k}#+E#{k}#', ef)], 'במכירה: בעמודת השווי כותבים את התמורה. הרווח או ההפסד: התמורה פחות השווי האחרון.', 'net'))
        else:
            out.append(LR(k, [d, ev, v, (f'=C#{k}#-C#{prev}#', ch), dv if dv != '' else 0, (f'=D#{k}#+E#{k}#', ef)], 'שלב 1: השווי בבורסה. שלב 2: פחות השווי בשורה הקודמת. שלב 3: דיבידנד (או 0). שלב 4: שינוי ועוד דיבידנד.' if i == 1 else ''))
    return LIVE(['תאריך', 'אירוע', 'שווי (במכירה: תמורה)', 'שינוי בשווי', 'דיבידנד', 'רווח והפסד'], out, [88, 105, 120, 92, 80, 92], center='AB',
                hints=['שינוי בשווי: השווי בשורה הזו פחות השווי בשורה הקודמת.', 'רווח והפסד: שינוי בשווי ועוד דיבידנד.'])


